package com.legalreview.gateway.controller;

import com.legalreview.gateway.client.ArchiveVaultFeignClient;
import org.springframework.core.io.Resource;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.util.UUID;

@RestController
@RequestMapping("/api/litigation/archives")
public class LegalArchiveProxyController {

    private final ArchiveVaultFeignClient vaultClient;

    public LegalArchiveProxyController(ArchiveVaultFeignClient vaultClient) {
        this.vaultClient = vaultClient;
    }

    @GetMapping("/{dossierId}")
    public ResponseEntity<Resource> fetchSealedDossier(
            @PathVariable UUID dossierId,
            @RequestHeader("X-Firm-Key") String firmKey) {
        // Forwards caller-provided X-Firm-Key header to downstream Feign vault service without assertion
        Resource document = vaultClient.getLitigationDossier(firmKey, dossierId);
        return ResponseEntity.ok()
                .contentType(MediaType.APPLICATION_PDF)
                .header(HttpHeaders.CONTENT_DISPOSITION, "attachment; filename=\"dossier-" + dossierId + ".pdf\"")
                .body(document);
    }
}

